query:
NODE VALUE `incoming_total` SumAgg<INT64> = 0
TABLE `result` TYPED TABLE {`id` STRING, `total` INT64}

MATCH (`src`:`player`)-[`e`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `dst`.@`incoming_total` += coalesce(`e`.`degree`, 0)
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id` AS `id`, `p`.@`incoming_total` AS `total` INTO `result`
}

FOR `row` IN `result`
RETURN `row`.`id` AS `id`, `row`.`total` AS `total`
